import { LeadStatus } from "@prisma/client";
import type { Metadata } from "next";
import Link from "next/link";
import { redirect } from "next/navigation";
import { updateLeadStatus } from "@/src/actions/vendor";
import { getCurrentUserProfile } from "@/src/lib/auth";
import { getVendorLeads } from "@/src/lib/leads";

export const dynamic = "force-dynamic";
export const metadata: Metadata = { title: "Vendor Leads", robots: { index: false, follow: false } };
type Props = { searchParams: Promise<{ page?: string; status?: string }> };
export default async function VendorLeadsPage({ searchParams }: Props) { const user = await getCurrentUserProfile(); if (!user) redirect("/sign-in?redirect_url=%2Fvendor%2Fleads"); const params = await searchParams; const status = Object.values(LeadStatus).includes(params.status as LeadStatus) ? params.status as LeadStatus : undefined; const result = await getVendorLeads(user.id, Number(params.page) || 1, status); return <main className="mx-auto min-h-[70vh] max-w-6xl px-4 py-12"><Link href="/vendor" className="text-caption font-semibold text-accent">← Vendor Dashboard</Link><div className="mt-6 flex flex-wrap items-end justify-between gap-4"><div><p className="overline">Commercial enquiries</p><h1 className="mt-2 text-h1 text-text-primary">Leads</h1></div><nav className="flex gap-2"><Link href="/vendor/leads" className="rounded border border-border px-3 py-1.5 text-caption">All</Link>{Object.values(LeadStatus).map((item) => <Link key={item} href={`/vendor/leads?status=${item}`} className="rounded border border-border px-3 py-1.5 text-caption">{item}</Link>)}</nav></div>{result.items.length ? <div className="mt-8 grid gap-4">{result.items.map((lead) => <article key={lead.id} className="card-surface p-5"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-caption text-text-tertiary">{lead.company.name}{lead.product && ` · ${lead.product.name}`} · {lead.createdAt.toLocaleDateString()}</p><h2 className="mt-2 text-h3 text-text-primary">{lead.name} · {lead.organization}</h2><p className="mt-1 text-caption text-text-secondary">{lead.jobTitle} · <a href={`mailto:${lead.email}`} className="text-accent">{lead.email}</a></p></div><form action={updateLeadStatus} className="flex gap-2"><input type="hidden" name="leadId" value={lead.id} /><select name="status" defaultValue={lead.status} className="rounded-md border border-border bg-bg px-2 py-1 text-caption">{Object.values(LeadStatus).map((item) => <option key={item}>{item}</option>)}</select><button className="rounded-md border border-border px-3 py-1 text-caption font-semibold">Update</button></form></div><p className="mt-4 whitespace-pre-line text-body text-text-secondary">{lead.message}</p></article>)}</div> : <div className="mt-8 rounded-lg border border-dashed border-border p-8 text-body text-text-secondary">No leads match this view yet.</div>}<nav className="mt-8 flex justify-between text-caption font-semibold">{result.page > 1 ? <Link href={`/vendor/leads?page=${result.page - 1}${status ? `&status=${status}` : ""}`} className="text-accent">← Previous</Link> : <span />}{result.page < result.pages && <Link href={`/vendor/leads?page=${result.page + 1}${status ? `&status=${status}` : ""}`} className="text-accent">Next →</Link>}</nav></main>; }
